window.__T__=[{"i":7200,"text":"一张具有真实感、原始航天局风格的照片，背景为 {argument name=\"setting\" default=\"火星地貌\"}，包含红色的土壤、散落的岩石和朦胧的橙色天空。在中景处，{argument name=\"objects\" default=\"两块刻有古老象形文字的深色石板\"} 以微小的角度从地面突出。在近景处，清晰的 {argument name=\"foreground element\" default=\"火星探测器的阴影\"} 投射在岩石地形上，展现出照片的视角。在图像顶部边缘，有一行简单的白色文字叠加层，类似于原始文件名，显示为 \"{argument name=\"overlay text\" default=\"ZCAM_0847_0734291854_678RAD_N0412172ZCAM08050_1100LUJ01.png\"}\"。光线强烈且真实，模拟了实际的地外表面摄影效果。","imgs":["https://r2.qqsrc.com/images/originals/13766.jpg"]},{"i":7201,"text":"{\"type\": \"YouTube 直播界面演示\", \"theme\": \"深色模式\", \"layout\": {\"top_bar\": {\"components\": [\"汉堡菜单\", \"YouTube logo\", \"搜索栏\", \"麦克风图标\", \"创建图标\", \"通知图标\", \"个人头像\"]}, \"video_player\": {\"status\": \"左上角显示 LIVE 徽标\", \"left_side\": \"一位 {argument name=\\\"presenter description\\\" default=\\\"身穿绿色毛衣的男士\\\"} 站在带有螺旋 logo 的木制讲台前，正在用手势交流，讲台上放着一台笔记本电脑。\", \"right_side_presentation\": {\"text_elements\": [\"OpenAI\", \"隆重推出\", \"{argument name=\\\"product name\\\" default=\\\"GPT-Image-2\\\"}\", \"{argument name=\\\"tagline\\\" default=\\\"更逼真、更实用、更具创造力。\\\"}\"], \"image_gallery\": {\"count\": 4, \"panels\": [\"带有小船的山间湖泊\", \"光影斑驳的女性特写肖像\", \"在黑暗森林中提着灯笼的可爱机器人\", \"夜晚发光城市街道的印象派画作\"]}}, \"bottom_controls\": {\"components\": [\"播放/暂停\", \"下一条\", \"音量\", \"LIVE 文字\", \"红色进度条\", \"CC\", \"设置齿轮\", \"迷你播放器\", \"影院模式\", \"全屏\"]}}, \"video_info\": {\"title\": \"{argument name=\\\"video title\\\" default=\\\"OpenAI 直播：隆重推出 GPT-Image-2\\\"}\", \"channel_section\": {\"name\": \"{argument name=\\\"channel name\\\" default=\\\"OpenAI\\\"}\", \"badge\": \"认证对勾\", \"subscribers\": \"136 万订阅者\", \"button\": \"订阅（白色胶囊按钮）\"}, \"action_buttons\": {\"count\": 5, \"labels\": [\"点赞 (1.2 万)\", \"不喜欢 (497)\", \"分享\", \"保存\", \"...\"]}, \"description_box\": {\"metadata\": \"95,237 人正在观看，直播开始于 7 分钟前\", \"hashtags\": \"#OpenAI #GPTImage2 #AI\", \"body_text\": \"欢迎参加我们的特别直播活动，我们将介绍 OpenAI 最新、最先进的图像生成模型 GPT-Image-2。了解新功能、观看实时演示，并聆听团队分享……更多\"}}}}","imgs":["https://r2.qqsrc.com/images/originals/13767.jpg"]},{"i":7202,"text":"{\n  \"type\": \"移动端直播 App 截图\",\n  \"subject\": {\n    \"description\": \"一只毛茸茸的可爱虎斑猫端坐着，两只前爪扶着一块白色长方形标语牌\",\n    \"sign_content\": {\n      \"text\": \"{argument name=\\\"sign text\\\" default=\\\"谢谢开发者 Hailey的大火箭！\\\"}\",\n      \"illustrations\": [\"粉色火箭\", \"黄色星星\", \"粉色爱心\"]\n    }\n  },\n  \"background\": {\n    \"setting\": \"光线温暖的舒适房间\",\n    \"elements\": [\"猫爬架\", \"发光的球形灯\", \"猫爪印装饰\"],\n    \"blackboard_text\": \"{argument name=\\\"background text\\\" default=\\\"欢迎来到 小猫咪的 直播间\\\"}\"\n  },\n  \"ui_layout\": {\n    \"status_bar\": {\n      \"time\": \"20:30\",\n      \"battery\": \"72\"\n    },\n    \"header\": {\n      \"host_info\": {\n        \"name\": \"{argument name=\\\"host name\\\" default=\\\"小猫咪的直播间\\\"}\",\n        \"likes\": \"123.4 万本场点赞\",\n        \"button\": \"关注\"\n      },\n      \"rank\": \"小时榜第 1 名\",\n      \"viewers\": {\n        \"count\": \"1.6 万\",\n        \"avatars_count\": 3\n      },\n      \"widgets\": [\n        \"更多直播 >\",\n        \"礼物展馆 24/28 经典\"\n      ]\n    },\n    \"gift_notification\": {\n      \"sender\": \"{argument name=\\\"gift sender\\\" default=\\\"Hailey\\\"}\",\n      \"action\": \"送 {argument name=\\\"gift name\\\" default=\\\"大火箭\\\"}\",\n      \"multiplier\": \"x1\",\n      \"badge\": \"真爱\"\n    },\n    \"chat_box\": {\n      \"message_count\": 7,\n      \"messages\": [\n        \"35 Hailey 送出 大火箭 🚀 x1\",\n        \"24 泡芙: 哇塞！大火箭！\",\n        \"18 可乐加冰: 棒棒哒猫猫~\",\n        \"7 小鱼干: 猫猫太可爱啦😍\",\n        \"12 云朵: 谢谢 Hailey 姐姐！\",\n        \"30 草莓奶昔: 冲冲冲🚀🚀🚀\",\n        \"5 用户123456789: 猫猫贴贴~\"\n      ]\n    },\n    \"floating_reactions\": [\n      \"粉色爱心\",\n      \"黄色爱心\",\n      \"蓝色爱心\",\n      \"大笑表情\"\n    ],\n    \"bottom_bar\": {\n      \"input_placeholder\": \"说点什么...\",\n      \"icons_count\": 4,\n      \"icons\": [\n        \"笑脸\",\n        \"爱心\",\n        \"礼物盒\",\n        \"省略号\"\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13768.jpg"]},{"i":7203,"text":"{\n  \"type\": \"落地页 UI 设计\",\n  \"theme\": \"深色模式，现代科技感，{argument name=\\\"primary accent color\\\" default=\\\"霓虹紫\\\"} 与蓝色发光点缀，玻璃拟态风格\",\n  \"header\": {\n    \"logo\": \"{argument name=\\\"brand name\\\" default=\\\"goViralX\\\"}\",\n    \"badge\": \"病毒式营销活动案例研究\"\n  },\n  \"sections\": [\n    {\n      \"id\": \"hero\",\n      \"layout\": \"左侧文字，右侧图片布局\",\n      \"content\": {\n        \"badge\": \"案例研究\",\n        \"headline\": \"{argument name=\\\"hero headline\\\" default=\\\"我们如何创造 1000 万+ 的病毒式影响力\\\"}\",\n        \"subtitle\": \"3 天引爆网络，助力品牌实现指数级增长\",\n        \"stats_row\": {\n          \"count\": 4,\n          \"labels\": [\"总浏览量 {argument name=\\\"main metric\\\" default=\\\"10,240,000+\\\"}\", \"互动率 18.7%\", \"转化量 3,200+\", \"执行周期 72 小时\"]\n        },\n        \"hero_image\": \"电影质感的镜头，展示一个人在暗室中注视着发光的悬浮视频屏幕，带有巨大的播放按钮叠加层\"\n      }\n    },\n    {\n      \"id\": \"strategy\",\n      \"title\": \"活动拆解：我们的 3 天执行策略\",\n      \"layout\": \"3 步垂直时间轴\",\n      \"steps\": [\n        {\"step\": 1, \"title\": \"策略制定\", \"image\": \"人们在屏幕上分析数据\"},\n        {\"step\": 2, \"title\": \"内容制作\", \"image\": \"视频编辑界面\"},\n        {\"step\": 3, \"title\": \"分发与放大\", \"image\": \"手持带有社交媒体图标的智能手机\"}\n      ]\n    },\n    {\n      \"id\": \"performance\",\n      \"title\": \"效果评估：数据驱动的绩效表现\",\n      \"layout\": \"左侧统计卡片网格，右侧图表\",\n      \"left_stats\": {\n        \"count\": 4,\n        \"labels\": [\"总曝光量 1000 万+\", \"平均 CPM 下降 43%\", \"新增粉丝 28,000+\", \"转化量 3,200+\"]\n      },\n      \"right_charts\": {\n        \"count\": 2,\n        \"items\": [\n          \"折线图显示 7 天趋势，在第 3 天达到 8,320,000 的峰值\",\n          \"横向柱状图显示平台分布：TikTok 52%，Instagram 24%，X 15%，YouTube 9%\"\n        ]\n      }\n    },\n    {\n      \"id\": \"keys_to_success\",\n      \"title\": \"为何能病毒式传播：成功的 3 大关键\",\n      \"layout\": \"3 张卡片横向排列\",\n      \"cards\": [\n        {\"icon\": \"fire\", \"title\": \"情感钩子设计\"},\n        {\"icon\": \"bullseye\", \"title\": \"内容结构设计\"},\n        {\"icon\": \"antenna\", \"title\": \"分发策略执行\"}\n      ]\n    },\n    {\n      \"id\": \"social_proof\",\n      \"title\": \"深受创作者与品牌信赖：他们都在使用 goViralX 实现增长\",\n      \"layout\": \"左侧 Logo，右侧客户评价\",\n      \"left_logos\": {\n        \"count\": 8,\n        \"labels\": [\"SHEIN\", \"SHOPLINE\", \"Blueglass\", \"instacart\", \"lemon8\", \"mi\", \"CIDER\", \"bellroy\"]\n      },\n      \"right_testimonials\": {\n        \"count\": 2,\n        \"labels\": [\"SaaS 创始人评价\", \"增长经理评价\"]\n      }\n    },\n    {\n      \"id\": \"cta\",\n      \"title\": \"准备好实现病毒式传播了吗？：想要获得同样的增长效果？\",\n      \"layout\": \"左侧文字与输入框，右侧 3D 插图\",\n      \"elements\": [\n        \"带有占位符文本的输入框\",\n        \"按钮：{argument name=\\\"call to action text\\\" default=\\\"获取专属增长方案 ->\\\"}\"\n      ],\n      \"image\": \"3D 发光紫色和蓝色火箭发射\"\n    }\n  ],\n  \"footer\": \"Logo 和版权声明文本\"\n}","imgs":["https://r2.qqsrc.com/images/originals/13769.jpg"]},{"i":7204,"text":"一张充满活力、高能量的 YouTube 直播封面，画面中是一位动漫风格的女孩，留着 {argument name=\"hair color\" default=\"蓝色\"} 的高马尾，有着明亮的蓝色眼睛和开心的笑容，身穿白色衬衫。她位于画面右侧。背景是 {argument name=\"background style\" default=\"闪烁的彩虹光束和金色闪粉\"} 的爆炸效果。左侧是巨大的 3D 金色金属文字，写着“{argument name=\"main title text\" default=\"初配信\"}”，并带有华丽的哥特式边框。下方是较小的金色与蓝色 3D 文字，写着“{argument name=\"subtitle text\" default=\"一緒に最高の時間を！\"}”。左下角是一个闪亮的金色复古麦克风。右上角是一个红色的矩形徽章，写着“▶ LIVE”。在画面中右侧、女孩脸部下方，是一个华丽的深蓝色与金色名牌，写着“{argument name=\"character name\" default=\"エリン Erin\"}”。整体风格超精细、华丽，是典型的 VTuber 初配信公告风格。","imgs":["https://r2.qqsrc.com/images/originals/13770.jpg"]},{"i":7205,"text":"{\n  \"type\": \"VTuber Logo 设计概念\",\n  \"theme\": \"{argument name=\\\"main theme\\\" default=\\\"哥特暗黑奇幻\\\"}\",\n  \"background\": \"{argument name=\\\"background color\\\" default=\\\"纯黑\\\"}\",\n  \"layout\": \"包含 6 个不同 Logo 设计的 2x3 网格\",\n  \"logos\": [\n    {\n      \"position\": \"左上\",\n      \"main_text\": \"{argument name=\\\"logo 1 main text\\\" default=\\\"魔界のメシア\\\"}\",\n      \"sub_text\": [\"魔界の観測者\", \"MAKAI NO KANSOKUSHA\"],\n      \"colors\": [\"紫色\", \"银色\"],\n      \"motifs\": [\"角\", \"发光的紫色眼睛\", \"蝙蝠翅膀\"]\n    },\n    {\n      \"position\": \"中上\",\n      \"main_text\": \"{argument name=\\\"logo 2 main text\\\" default=\\\"深淵プレシア\\\"}\",\n      \"sub_text\": [\"Shinen Lucia\", \"魔界の断罪者\"],\n      \"colors\": [\"红色\", \"黑色\", \"金色\"],\n      \"motifs\": [\"锁链\", \"恶魔尖刺\", \"发光的红色符文\"]\n    },\n    {\n      \"position\": \"右上\",\n      \"main_text\": \"{argument name=\\\"logo 3 main text\\\" default=\\\"夢喰いメフィ\\\"}\",\n      \"sub_text\": [\"まかいのゆめくい\"],\n      \"colors\": [\"粉色\", \"紫色\"],\n      \"motifs\": [\"带皇冠的骷髅\", \"蝙蝠翅膀\", \"闪光效果\"]\n    },\n    {\n      \"position\": \"左下\",\n      \"main_text\": \"苍影カナタ\",\n      \"sub_text\": [\"魔界の影诗人\", \"- AOKAGE KANATA -\"],\n      \"colors\": [\"蓝色\", \"银色\"],\n      \"motifs\": [\"巨大的中央眼睛\", \"银色蝙蝠翅膀\", \"哥特式建筑\"]\n    },\n    {\n      \"position\": \"中下\",\n      \"main_text\": \"黄昏ベリアル\",\n      \"sub_text\": [\"Tasogare Belial\", \"魔界の王子\"],\n      \"colors\": [\"金色\", \"紫色\"],\n      \"motifs\": [\"皇冠\", \"蝙蝠翅膀\", \"悬挂的宝石\"]\n    },\n    {\n      \"position\": \"右下\",\n      \"main_text\": \"祸胧シオン\",\n      \"sub_text\": [\"魔界の记忆屋\", \"- MAGATSU SHION -\"],\n      \"colors\": [\"银色\", \"紫色\", \"黑色\"],\n      \"motifs\": [\"新月\", \"发光的紫色火焰\", \"锁链\", \"暗黑烟雾\"]\n    }\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/13771.jpg"]},{"i":7206,"text":"{\n  \"type\": \"照片级逼真的印刷试卷\",\n  \"style\": \"米白色微皱纸张上的黑色文字，真实的文档摄影效果\",\n  \"header\": {\n    \"main_title\": \"{argument name=\\\"exam title\\\" default=\\\"玉林市 2024 年春季期高一期末教学质量监测试卷\\\"}\",\n    \"subject\": \"{argument name=\\\"subject name\\\" default=\\\"数 学 试 卷\\\"}\",\n    \"details\": \"{argument name=\\\"score and time\\\" default=\\\"本试卷满分 150 分，考试时间 120 分钟。\\\"}\"\n  },\n  \"layout\": {\n    \"instructions\": {\n      \"title\": \"注意事项:\",\n      \"point_count\": 3,\n      \"content\": \"关于答题卡、2B 铅笔和交卷的标准考试规则。\"\n    },\n    \"main_section\": {\n      \"heading\": \"{argument name=\\\"section title\\\" default=\\\"一、选择题: 本题共 8 小题，每小题 5 分，共 40 分。在每小题给出的四个选项中，只有一项是符合题目要求的。\\\"}\",\n      \"question_count\": 8,\n      \"format\": \"从 1 到 8 的编号列表，每题包含数学公式和 4 个选项 (A, B, C, D)。\",\n      \"topics\": [\n        \"集合交集\",\n        \"复数\",\n        \"单调递增函数\",\n        \"充要条件\",\n        \"向量与三角函数\",\n        \"立体几何\",\n        \"圆锥侧面积\",\n        \"三角函数图像\"\n      ],\n      \"diagrams\": {\n        \"count\": 2,\n        \"descriptions\": [\n          \"位于第 6 题旁边的立方体 3D 线框图，带有内部虚线。\",\n          \"位于第 8 题旁边的二维笛卡尔坐标系图，显示部分正弦波曲线。\"\n        ]\n      }\n    },\n    \"footer\": \"{argument name=\\\"footer text\\\" default=\\\"高一数学试卷 第 1 页 (共 4 页)\\\"}\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13773.jpg"]},{"i":7207,"text":"{\n  \"type\": \"应用宣传信息图海报\",\n  \"style\": \"简洁、现代、磨砂玻璃风格、柔和阴影、3D 图标\",\n  \"theme\": \"{argument name=\\\"primary color theme\\\" default=\\\"蓝白配色\\\"}\",\n  \"header\": {\n    \"title\": \"{argument name=\\\"app name\\\" default=\\\"CodePilot\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"你的 AI 编程副驾驶\\\"}\",\n    \"features_list\": \"智能补全 · 代码生成 · 问答调试 · 代码解析\",\n    \"main_icon\": \"光泽感 3D 圆角正方形，蓝色渐变，白色 {argument name=\\\"main icon symbol\\\" default=\\\"</>\\\"} 及闪光效果\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"feature_cards\",\n        \"position\": \"中间网格\",\n        \"count\": 4,\n        \"items\": [\n          {\n            \"label\": \"智能代码补全\",\n            \"icon\": \"蓝色闪电\",\n            \"description\": \"上下文感知，精准补全，让编码快人一步\",\n            \"ui_element\": \"macOS 风格代码窗口，展示 Python calculate_total 函数\"\n          },\n          {\n            \"label\": \"AI 代码生成\",\n            \"icon\": \"紫色魔法棒\",\n            \"description\": \"根据自然语言描述，一键生成函数与脚本\",\n            \"ui_element\": \"聊天提示气泡和展示 Python quick_sort 函数的代码窗口\"\n          },\n          {\n            \"label\": \"对话 & 调试助手\",\n            \"icon\": \"绿色聊天气泡\",\n            \"description\": \"通过自然语言提问定位 Bug，边聊边改，高效解决问题\",\n            \"ui_element\": \"包含用户提问和绿色 AI 解决方案气泡的聊天界面\"\n          },\n          {\n            \"label\": \"代码解析 & 注释\",\n            \"icon\": \"带有放大镜的橙色文档\",\n            \"description\": \"快速理解复杂代码，自动生成注释与说明\",\n            \"ui_element\": \"展示 JS fetchData 函数的代码窗口，带有 3 个浮动操作标签：自动注释、逻辑解析、一键复制\"\n          }\n        ]\n      },\n      {\n        \"title\": \"为什么选择 CodePilot？\",\n        \"position\": \"左下角\",\n        \"count\": 4,\n        \"labels\": [\"提升效率\", \"精准可靠\", \"隐私安全\", \"易于集成\"],\n        \"icons\": [\"时钟\", \"对勾\", \"盾牌\", \"拼图块\"]\n      },\n      {\n        \"title\": \"立即体验\",\n        \"position\": \"右下角\",\n        \"count\": 1,\n        \"elements\": [\"GitHub 开源项目\", \"{argument name=\\\"github link\\\" default=\\\"github.com/op7418/CodePilot\\\"}\", \"二维码\"]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13774.jpg"]},{"i":7208,"text":"一张明亮清爽的商业摄影作品，主角为一位 {argument name=\"subject description\" default=\"留着黑色短发的帅气年轻亚裔男性\"}，身穿一件 {argument name=\"clothing\" default=\"浅蓝色针织毛衣\"}。他面带柔和微笑，直视镜头，手中拿着一瓶挂着水珠的透明塑料水瓶。瓶身贴有亮蓝色标签，上面印有白色文字“{argument name=\"product label\" default=\"POCARI SWEAT\"}”。背景分为两部分：左侧窗外可见清澈的浅蓝色天空，右侧为柔焦处理的温馨室内，配有相框和暖色调台灯。左下角有清晰的白色叠加文字，显示为“{argument name=\"overlay text line 1\" default=\"포카리 스웨트\"}”，下方是一行更大的文字“{argument name=\"overlay text line 2\" default=\"이온을 채워, 순간을 살아\"}”，并配有底部的白色弧形动感图形。整体光线柔和、自然且通透，营造出一种纯净、补水的氛围。","imgs":["https://r2.qqsrc.com/images/originals/13776.jpg"]},{"i":7209,"text":"{\n  \"type\": \"猫咪全品种科普图鉴\",\n  \"header\": {\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"猫咪全品种科普图鉴\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"涵盖全球所有猫咪品种 | 名称 & 性格特点\\\"}\",\n    \"decorations\": [\"猫爪印\"]\n  },\n  \"layout\": {\n    \"style\": \"基于网格的图表，配有水平色块分区\",\n    \"columns\": 9\n  },\n  \"sections\": [\n    {\n      \"title\": \"{argument name=\\\"category 1 name\\\" default=\\\"短毛猫\\\"}\",\n      \"background_color\": \"浅绿色\",\n      \"total_cats\": 18,\n      \"rows\": 2,\n      \"labels\": [\"美国短毛猫\", \"英国短毛猫\", \"欧洲短毛猫\", \"中国狸花猫\", \"暹罗猫\", \"缅甸猫\", \"阿比西尼亚猫\", \"孟加拉猫\", \"埃及猫\", \"奥西猫\", \"东方短毛猫\", \"柯尼斯卷毛猫\", \"德文卷毛猫\", \"斯芬克斯猫\", \"彼得秃猫\", \"美国刚毛猫\", \"日本短尾猫\", \"曼岛猫\"],\n      \"item_format\": \"猫咪肖像 + 品种名称 + 性格描述\"\n    },\n    {\n      \"title\": \"{argument name=\\\"category 2 name\\\" default=\\\"长毛猫\\\"}\",\n      \"background_color\": \"浅粉色\",\n      \"total_cats\": 18,\n      \"rows\": 2,\n      \"labels\": [\"波斯猫\", \"缅因猫\", \"布偶猫\", \"挪威森林猫\", \"西伯利亚猫\", \"土耳其安哥拉猫\", \"土耳其梵猫\", \"伯曼猫\", \"美国长毛猫\", \"金吉拉猫\", \"喜马拉雅猫\", \"苏格兰折耳长毛猫\", \"塞尔凯克卷毛猫\", \"拉邦猫\", \"索马里猫\", \"巴厘猫\", \"东方长毛猫\", \"狮子猫\"],\n      \"item_format\": \"猫咪肖像 + 品种名称 + 性格描述\"\n    },\n    {\n      \"title\": \"{argument name=\\\"category 3 name\\\" default=\\\"稀有及特色猫\\\"}\",\n      \"background_color\": \"浅黄色\",\n      \"total_cats\": 18,\n      \"rows\": 2,\n      \"labels\": [\"布里蒂猫\", \"俄罗斯蓝猫\", \"沙特尔猫\", \"哈瓦那棕猫\", \"新加坡猫\", \"孟买猫\", \"斯诺鞋猫\", \"玩具虎猫\", \"威尔士猫\", \"美国卷耳猫\", \"苏格兰折耳猫(短毛)\", \"异国短毛猫\", \"加菲猫\", \"美国反耳猫\", \"薮猫(萨凡纳猫)\", \"狞猫(卡拉卡尔)\", \"狮子猫(大型)\", \"豹猫(亚洲豹猫)\"],\n      \"item_format\": \"猫咪肖像 + 品种名称 + 性格描述\"\n    },\n    {\n      \"title\": \"无毛及卷毛猫\",\n      \"background_color\": \"浅蓝色\",\n      \"total_cats\": 9,\n      \"rows\": 1,\n      \"labels\": [\"顿斯科伊猫\", \"彼得秃猫(巴尔德)\", \"精灵猫(双耳卷)\", \"加拿大无毛猫\", \"乌克兰勒夫科伊猫\", \"明斯金猫(短腿无毛)\", \"拉邦猫(卷毛无毛)\", \"德文卷毛猫\", \"柯尼斯卷毛猫\"],\n      \"item_format\": \"猫咪肖像 + 品种名称 + 性格描述\"\n    }\n  ],\n  \"footer\": {\n    \"left_section\": {\n      \"title\": \"小贴士:\",\n      \"content\": \"3 条带编号的宠物护理建议\"\n    },\n    \"right_section\": {\n      \"title\": \"图例说明:\",\n      \"content\": \"4 个与各分区背景色对应的颜色图例框\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13780.jpg"]},{"i":7210,"text":"{\n  \"type\": \"移动端直播界面设计稿\",\n  \"scene\": {\n    \"subject\": \"{argument name=\\\"main subject\\\" default=\\\"Sam Altman\\\"} 的肖像，身穿深绿色毛衣，直视镜头，右手向前伸出，做出邀请的手势。\",\n    \"background\": \"办公室演播室场景。左侧为巨大的 'OpenAI' 墙面 Logo。右侧为木质搁架，上面摆放着 3 瓶深色葡萄酒和 2 块小型方形铭牌，其中一块写着 'AGI'，另一块写着 'OpenAI'。\"\n  },\n  \"layout\": {\n    \"top_overlay\": {\n      \"status_bar\": \"时间 '20:34'，蜂窝信号栏，Wi-Fi 图标，电量 '774'\",\n      \"host_profile\": \"OpenAI Logo，名称 'OpenAI'，副标题 '483k 人喜欢本场直播'，红色 '关注' 按钮\",\n      \"viewer_stats\": \"3 个用户头像，文本 '100k+'，'X' 关闭图标\",\n      \"banners\": [\n        \"顶部排名横幅，显示 'OpenAI 官方旗舰店排名 #1'\",\n        \"链接显示 '更多直播 >'\",\n        \"红包倒计时图标 '00:12'\",\n        \"礼盒图标，显示 '520 礼遇季抖音商城推荐'\"\n      ]\n    },\n    \"bottom_left_overlay\": {\n      \"pinned_host_message\": {\n        \"avatar\": \"主播肖像\",\n        \"name\": \"Sam Altman\",\n        \"badge\": \"直播中\",\n        \"message\": \"{argument name=\\\"host message\\\" default=\\\"大家好，我是山姆奥特曼，邀你加入Kevin的学堂\\\"}\"\n      },\n      \"live_chat\": {\n        \"count\": 5,\n        \"messages\": [\n          \"32 级勋章，用户 'AI beginner'，内容 '只是想来学习，我到了！'\",\n          \"18 级勋章，用户 'Xiaokai'，内容 '终于开播了，冲冲冲！'\",\n          \"7 级勋章，用户 'Worker Kevin'，内容 '一人公司太棒了！'\",\n          \"26 级勋章，用户 'Smart Future'，内容 '已关注，期待内容！'\",\n          \"5 级勋章，用户 'AI Side Hustle Guide'，内容 '怎么加入？'\"\n        ]\n      }\n    },\n    \"bottom_right_overlay\": {\n      \"qr_code_card\": {\n        \"graphic\": \"大型可扫描二维码，中心带有蓝色 Logo，写着 'KEVIN'\",\n        \"primary_text\": \"{argument name=\\\"promo headline\\\" default=\\\"零基础做AI一人公司\\\"}\",\n        \"secondary_text\": \"{argument name=\\\"promo subheadline\\\" default=\\\"将创业变赚钱生意\\\"}\",\n        \"call_to_action_button\": \"红色按钮，显示 {argument name=\\\"button text\\\" default=\\\"扫码加入\\\"}\"\n      }\n    },\n    \"bottom_navigation_bar\": {\n      \"input_field\": \"文本框显示 '说点什么...'\",\n      \"icons_count\": 5,\n      \"icons\": [\n        \"笑脸表情图标\",\n        \"购物车图标\",\n        \"爱心图标\",\n        \"礼盒图标\",\n        \"三点菜单图标\"\n      ],\n      \"system\": \"底部 iOS 主屏幕指示条\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13782.jpg"]},{"i":7211,"text":"一幅 {argument name=\"art style\" default=\"中国传统水墨画\"}，描绘了巨大的 {argument name=\"mecha subject\" default=\"初号机\"} 融入云雾缭绕的山水景观中。机甲的紫色与 {argument name=\"accent color\" default=\"玉绿色\"} 机身与嶙峋的岩石和深色的墨迹融为一体，其带角的头部从浓雾中显现。场景包含陡峭的悬崖、瀑布、松树、小型传统宝塔，以及一群飞鸟穿过中央的薄雾。左上角的竖排中文书法写着“{argument name=\"main calligraphy text\" default=\"初号机\"}”和“{argument name=\"secondary calligraphy text\" default=\"人之造物 亦为山水\"}”，并配有红色印章。右下角有第二个红色印章。整幅作品呈现出富有表现力的笔触、墨迹晕染以及复古纸张的质感。","imgs":["https://r2.qqsrc.com/images/originals/13784.jpg"]},{"i":7212,"text":"一幅细节极其丰富的 {argument name=\"art style\" default=\"中国传统水墨画\"}，描绘了一场户外宴饮。画面上方，一幅展开的卷轴上书写着汉字书法 {argument name=\"scroll text\" default=\"君不見，黃河之水天上來\"}。下方山水景观中，左侧有瀑布与红日，右侧有水上亭台与满月。前景中，10 位人物围坐在石桌旁。中央那位身着白袍的蓄须男子正 {argument name=\"central figure action\" default=\"站立并举杯向天\"}。他周围有 8 位坐着的文人正在饮酒，还有 1 名侍童抱着酒坛。桌上摆放着水果和金属酒壶。地上放着大型陶瓷酒坛。左侧，3 只山羊在岩石间休憩。右侧背景中，1 位人物正骑马经过松树旁。","imgs":["https://r2.qqsrc.com/images/originals/13785.jpg"]},{"i":7213,"text":"{\n  \"type\": \"3D 动画风格旅游宣传海报\",\n  \"typography\": {\n    \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"广西\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"山水甲天下，多彩广西\\\"}\"\n  },\n  \"characters\": [\n    {\n      \"position\": \"左侧中心\",\n      \"description\": \"3D 动画女孩，表情愉悦\",\n      \"outfit\": \"{argument name=\\\"left character outfit\\\" default=\\\"带有银饰头饰的传统少数民族服饰\\\"}\"\n    },\n    {\n      \"position\": \"右侧中心\",\n      \"description\": \"3D 动画女孩，表情愉悦\",\n      \"outfit\": \"{argument name=\\\"right character outfit\\\" default=\\\"带有斗笠的白色传统服饰\\\"}\"\n    }\n  ],\n  \"background\": {\n    \"theme\": \"{argument name=\\\"region theme\\\" default=\\\"广西喀斯特地貌与河流\\\"}\",\n    \"style\": \"郁郁葱葱的 3D 等距地图\",\n    \"map_labels\": [\n      \"德天跨国瀑布\",\n      \"桂林·象鼻山\",\n      \"龙脊梯田\",\n      \"阳朔·遇龙河\"\n    ]\n  },\n  \"layout\": {\n    \"polaroid_photos\": {\n      \"count\": 4,\n      \"items\": [\n        { \"position\": \"左上\", \"label\": \"三江·程阳风雨桥\", \"scene\": \"传统风雨桥\" },\n        { \"position\": \"左中\", \"label\": \"北海·银滩\", \"scene\": \"热带海滩\" },\n        { \"position\": \"左下\", \"label\": \"北海·银滩\", \"scene\": \"热带海滩\" },\n        { \"position\": \"右下\", \"label\": \"靖西·鹅泉\", \"scene\": \"水上石拱桥\" }\n      ]\n    },\n    \"food_showcase\": {\n      \"position\": \"底部前景\",\n      \"count\": 4,\n      \"items\": [\n        { \"label\": \"柳州螺蛳粉\", \"description\": \"一碗香辣螺蛳粉\" },\n        { \"label\": \"南宁老友粉\", \"description\": \"一碗肉片汤底米粉\" },\n        { \"label\": \"五色糯米饭\", \"description\": \"装在竹篮里的五色糯米饭\" },\n        { \"label\": \"荔浦芋头\", \"description\": \"完整及切开的芋头\" }\n      ]\n    },\n    \"decorations\": \"散落的黄色桂花和红色木槿花\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13786.jpg"]},{"i":7214,"text":"一幅高度细节化的 {argument name=\"art style\" default=\"超写实电影级 3D 渲染图\"}，展现了 {argument name=\"historical setting\" default=\"灵感源自《清明上河图》的中国古代街景\"}。采用俯瞰的广角视角，俯瞰着一个熙熙攘攘的土路十字路口，四周环绕着带有精致灰瓦屋顶的传统木质建筑。左侧的一座建筑挂着写有“安居客栈”的招牌，门外悬挂着红灯笼。场景中挤满了数十名身着传统古装的村民、商人和旅人。人们正在进行各种活动：挑着担子运送编织篮、在大型木伞下照看摊位、骑马，右下角还有人拉着一辆带有大辐条轮的木车。商店中央矗立着一棵枝繁叶茂的绿树，垂柳枝条勾勒出最左侧的前景。氛围生动且带有尘土气息，在 {argument name=\"lighting\" default=\"温暖的午后阳光\"} 的照耀下，在纹理丰富、细节极其精细的环境中投射出清晰而复杂的阴影。","imgs":["https://r2.qqsrc.com/images/originals/13788.jpg"]},{"i":7215,"text":"{\n  \"type\": \"长图垂直信息图\",\n  \"style\": \"现代科技风，3D 等轴测插图，深紫与蓝色调，玻璃拟态 UI 元素\",\n  \"header\": {\n    \"logo\": \"{argument name=\\\"company logo\\\" default=\\\"ANTHROPIC\\\"}\",\n    \"badge\": \"最新发布\",\n    \"title\": \"{argument name=\\\"product name\\\" default=\\\"Claude Opus 4.7\\\"}\",\n    \"subtitle\": \"{argument name=\\\"main subtitle\\\" default=\\\"当前最强的 Claude 模型\\\"}\",\n    \"tagline\": \"更强大、更稳定、更像真正的 AI 员工！\",\n    \"illustration\": \"3D 可爱机器人坐在桌前，配有笔记本电脑、咖啡杯和悬浮的代码窗口\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"6 大关键升级\",\n        \"icon\": \"3D 金色奖杯\",\n        \"layout\": \"2x3 网格\",\n        \"count\": 6,\n        \"items\": [\n          {\"title\": \"复杂任务能力显著提升\", \"icon\": \"3D 带有勾选标记的剪贴板\"},\n          {\"title\": \"Agent 编程能力大幅增强\", \"icon\": \"3D 代码终端窗口\"},\n          {\"title\": \"多模态能力更强\", \"icon\": \"3D 图像与文本文档\"},\n          {\"title\": \"专业工作能力提升\", \"icon\": \"3D 饼图与柱状图\"},\n          {\"title\": \"超大上下文 (1M Tokens)\", \"icon\": \"3D 带有 1,000,000 Tokens 字样的文档\"},\n          {\"title\": \"当前最强通用模型\", \"icon\": \"3D 紫色奖杯，带有 OPUS 4.7 字样\"}\n        ]\n      },\n      {\n        \"title\": \"简单理解：4.6 vs 4.7\",\n        \"icon\": \"3D 天平\",\n        \"layout\": \"并排对比，中间带有向右箭头\",\n        \"count\": 2,\n        \"columns\": [\n          {\n            \"header\": \"{argument name=\\\"comparison version 1\\\" default=\\\"Claude 4.6\\\"}\",\n            \"quote\": \"很强的工具人\",\n            \"style\": \"灰色方框\"\n          },\n          {\n            \"header\": \"{argument name=\\\"comparison version 2\\\" default=\\\"Claude 4.7\\\"}\",\n            \"quote\": \"可以独立做项目的 AI 员工\",\n            \"style\": \"紫色方框，高亮显示\"\n          }\n        ]\n      },\n      {\n        \"title\": \"谁最适合使用 Claude Opus 4.7？\",\n        \"icon\": \"3D 目标靶\",\n        \"layout\": \"水平排列\",\n        \"count\": 4,\n        \"labels\": [\n          \"开发者\",\n          \"AI 创业者\",\n          \"数据分析师\",\n          \"产品团队\"\n        ]\n      }\n    ],\n    \"footer\": {\n      \"title\": \"一句话总结\",\n      \"icon\": \"3D 灯泡\",\n      \"main_text\": \"Claude Opus 4.7 不只是更聪明，而是更可靠、更能干、更像真正的 AI 员工。\",\n      \"sub_text\": \"如果你要构建未来的 AI 应用，4.7 是当前最值得选择的模型。\",\n      \"illustration\": \"3D 可爱机器人竖起大拇指\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13789.jpg"]},{"i":7216,"text":"一张带有横向四联分屏布局和粗黑边框的桌面壁纸。它展示了半身肖像，采用高对比度的 {argument name=\"art style\" default=\"木刻版画\"} 风格，运用粗线条和交叉排线，传达出自信且精英的氛围。从左至右依次为：背景为纹理橙色的 {argument name=\"subject 1\" default=\"马云\"}；背景为纹理红色的身着西装的 {argument name=\"subject 2\" default=\"埃隆·马斯克\"}；背景为纹理蓝色的身着黑色衬衫的 {argument name=\"subject 3\" default=\"马克·扎克伯格\"}；以及背景为纹理绿色、戴眼镜穿西装的 {argument name=\"subject 4\" default=\"马化腾\"}。人物主体以单色米色调呈现，与每个分屏鲜艳的背景形成强烈对比。","imgs":["https://r2.qqsrc.com/images/originals/13791.jpg"]},{"i":7217,"text":"{\n  \"type\": \"3D 皮克斯风格动画插画\",\n  \"composition\": \"两个性格迥异的角色坐在书桌前，采用分屏美学，左侧凌乱，右侧整洁\",\n  \"floating_text\": {\n    \"left\": \"{argument name=\\\"left character name\\\" default=\\\"OPUS 4.6 THINKING\\\"} 使用发光的红色手写字体\",\n    \"right\": \"{argument name=\\\"right character name\\\" default=\\\"CODEX\\\"} 使用发光的蓝色霓虹字体\"\n  },\n  \"characters\": [\n    {\n      \"position\": \"左侧\",\n      \"persona\": \"叛逆、激进的程序员\",\n      \"appearance\": \"凌乱的棕色头发，自信的坏笑，嘴里叼着烟，脖子上有“NO RULES”纹身\",\n      \"clothing\": \"带有铆钉的黑色皮夹克，黑色 T 恤上印有“{argument name=\\\"left shirt text\\\" default=\\\"FAST. BOLD. BROKEN. BUT IT WORKS... SOMETIMES.\\\"}”\",\n      \"pose\": \"手臂搭在右侧角色身上，手里拿着写有“DEPLOY OR DIE”的黑色易拉罐\"\n    },\n    {\n      \"position\": \"右侧\",\n      \"persona\": \"有条理、稳重的程序员\",\n      \"appearance\": \"整洁的棕色头发，圆框眼镜，表情紧张但顺从\",\n      \"clothing\": \"舒适的灰色开衫，带有树木标志，衬衫领口，袖口贴片写着“READ. PLAN. REFACTOR. DELIVER.”\",\n      \"pose\": \"双手捧着写有“{argument name=\\\"right mug text\\\" default=\\\"CODE. THINK. IMPROVE.\\\"}”的白色马克杯\"\n    }\n  ],\n  \"environment\": {\n    \"left_side\": {\n      \"vibe\": \"混乱且凌乱\",\n      \"props\": [\n        \"显示着彩色代码的电脑显示器\",\n        \"写有“BUGS ARE FEATURES”的黑色马克杯\",\n        \"5 张揉皱的纸团\",\n        \"桌上贴着 1 张便签，写着“TODO: 完成一半的用户系统。。。算了明天再说。”\"\n      ],\n      \"whiteboard\": {\n        \"title\": \"OPUS 的作风:\",\n        \"bullet_points_count\": 5,\n        \"sticky_notes_count\": 2,\n        \"sticky_notes_text\": [\"先实现再说！\", \"一个文件搞定全部！\"]\n      }\n    },\n    \"right_side\": {\n      \"vibe\": \"结构化且整洁\",\n      \"props\": [\n        \"打开的笔记本，上面有 6 项清单，标题为“执行计划:”，并贴有一张黄色便签“让代码变得更好。”\",\n        \"一叠 5 本深色书籍，书脊文字为：“PRODUCT REQUIREMENTS.md”、“ARCHITECTURE.md”、“.claude”、“CODEBASE ANALYSIS.md”、“REFACTOR PLAN.md”\",\n        \"桌上放着整齐的架构蓝图\"\n      ],\n      \"whiteboard\": {\n        \"title\": \"CODEX 的作风:\",\n        \"bullet_points_count\": 5,\n        \"sticky_notes_count\": 3,\n        \"sticky_notes_text\": [\"先读文档理解架构\", \"制定计划再开始\", \"顺便把这段代码重构一下\"]\n      }\n    }\n  },\n  \"foreground\": {\n    \"plaque\": \"书桌前缘的金属铭牌，刻有文字“{argument name=\\\"plaque text\\\" default=\\\"最佳拍档 一个激进，一个稳重，刚好互补。♡\\\"}”\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13792.jpg"]},{"i":7218,"text":"{\n  \"type\": \"教育信息图海报\",\n  \"header\": {\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"一图读懂 导演分镜思维\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"从脚本到画面：导演如何用分镜讲好一个故事\\\"}\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"1. 分镜是什么？\",\n        \"components\": [\n          \"定义文本框\",\n          {\n            \"type\": \"flowchart\",\n            \"count\": 5,\n            \"labels\": [\"文字脚本\", \"导演分镜思维\", \"分镜画面\", \"拍摄执行\", \"成片呈现\"]\n          }\n        ]\n      },\n      {\n        \"title\": \"2. 导演分镜思维的核心步骤\",\n        \"count\": 5,\n        \"labels\": [\"① 理解剧本\", \"② 拆解场景\", \"③ 设计镜头\", \"④ 视觉调度\", \"⑤ 组接节奏\"]\n      },\n      {\n        \"title\": \"3. 分镜的基本构成（以一个镜头为例）\",\n        \"columns\": [\n          {\n            \"position\": \"left\",\n            \"count\": 8,\n            \"labels\": [\"镜号\", \"景别\", \"机位\", \"运动\", \"时长\", \"内容\", \"台词/音效\", \"备注\"]\n          },\n          {\n            \"position\": \"center\",\n            \"image\": \"{argument name=\\\"character subject\\\" default=\\\"anime girl reading in a room\\\"}\"\n          },\n          {\n            \"position\": \"right\",\n            \"title\": \"小技巧\",\n            \"count\": 3,\n            \"description\": \"图标要点\"\n          }\n        ]\n      },\n      {\n        \"title\": \"4. 分镜如何服务于叙事？\",\n        \"subtitle\": \"{argument name=\\\"example scenario\\\" default=\\\"举例：女孩在房间听到异响\\\"}\",\n        \"count\": 4,\n        \"panels\": [\"房间全景\", \"女孩阅读中景\", \"女孩抬头中景\", \"门打开特写\"],\n        \"caption_labels\": [\"镜号\", \"景别\", \"机位\", \"时长\", \"内容\", \"作用\"]\n      },\n      {\n        \"title\": \"5. 导演分镜思维的进阶心法\",\n        \"count\": 5,\n        \"labels\": [\"以观众视角思考\", \"情绪优先于技术\", \"删繁就简\", \"控制节奏\", \"保持整体感\"]\n      }\n    ],\n    \"footer\": \"{argument name=\\\"footer quote\\\" default=\\\"好的分镜，是导演脑中电影的第一次放映。\\\"}\"\n  },\n  \"style\": \"简洁商务风信息图，蓝白配色，结构化网格\"\n}","imgs":["https://r2.qqsrc.com/images/originals/13793.jpg"]},{"i":7219,"text":"{\n  \"type\": \"生物概念艺术参考图\",\n  \"style\": \"复古野外指南，羊皮纸背景，写实风格插画\",\n  \"subject\": {\n    \"name\": \"{argument name=\\\"creature name\\\" default=\\\"Gojinya\\\"}\",\n    \"japanese_name\": \"{argument name=\\\"japanese name\\\" default=\\\"ごじにゃ\\\"}\",\n    \"base_animal\": \"{argument name=\\\"base animal\\\" default=\\\"黑猫\\\"}\",\n    \"hybrid_element\": \"{argument name=\\\"hybrid element\\\" default=\\\"哥斯拉\\\"}\",\n    \"features\": \"黑色皮毛，发光的蓝色背鳍，黄色眼睛\"\n  },\n  \"layout\": {\n    \"header\": { \"text\": [\"{argument name=\\\"japanese name\\\" default=\\\"ごじにゃ\\\"}\", \"{argument name=\\\"creature name\\\" default=\\\"Gojinya\\\"}\"], \"style\": \"蓝色发光字体\" },\n    \"main_portrait\": \"全身像，以怪兽姿态后腿站立，脚下有烟雾/火焰，附带人类剪影比例尺\",\n    \"text_sections\": [\n      { \"title\": \"物种\", \"bullet_count\": 4 },\n      { \"title\": \"能力\", \"bullet_count\": 2 },\n      { \"title\": \"特征\", \"bullet_count\": 2 },\n      { \"title\": \"喜好\", \"bullet_count\": 4 },\n      { \"title\": \"厌恶\", \"bullet_count\": 4 },\n      { \"title\": \"习性\", \"bullet_count\": 3 },\n      { \"title\": \"厌恶\", \"bullet_count\": 3 }\n    ],\n    \"action_panels\": [\n      \"右上角插图：发射蓝色原子吐息的头部特写\",\n      \"左下角插图：全身发射蓝色原子吐息，摧毁岩石\"\n    ],\n    \"sketches\": {\n      \"title\": \"草图\",\n      \"count\": 5,\n      \"items\": [\"坐姿猫\", \"普通肉垫\", \"发光的蓝色肉垫\", \"咆哮的头部\", \"带有音符的开心头部\"]\n    },\n    \"additional_poses\": {\n      \"count\": 2,\n      \"items\": [\"带比例尺的站立姿势\", \"侧面坐姿\"]\n    },\n    \"color_palette\": {\n      \"swatch_count\": 5,\n      \"colors\": [\"橙色\", \"黑色\", \"灰色\", \"浅蓝色\", \"亮蓝色\"]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13795.jpg"]},{"i":7220,"text":"{\n  \"type\": \"宣传信息图海报\",\n  \"theme\": \"赛博朋克霓虹 AI 音乐，深色背景，发光的紫/蓝/粉色调\",\n  \"header\": {\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"YouMind AI 音乐人计划\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"助力 AI 创作者实现发行、签约与商业化\\\"}\",\n    \"visual\": \"音乐制作人背影，佩戴耳机坐在桌前，双显示器显示 DAW 界面，配有 MIDI 键盘，夹克上印有发光的 'AI MUSIC' 字样，背景为演唱会人群\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"{argument name=\\\"features section title\\\" default=\\\"YouMind 为 AI 音乐人提供完整成长支持\\\"}\",\n        \"count\": 4,\n        \"items\": [\n          {\"label\": \"01 高倍口发行支持\", \"icon\": \"发光的 3D 音符\"},\n          {\"label\": \"02 百万推广资源扶持\", \"icon\": \"发光的 3D 扩音器\"},\n          {\"label\": \"03 商业合作与版权支持\", \"icon\": \"发光的 3D 文档\"},\n          {\"label\": \"04 签约孵化通道\", \"icon\": \"发光的 3D 麦克风与星星\"}\n        ]\n      },\n      {\n        \"title\": \"{argument name=\\\"partners section title\\\" default=\\\"YouMind 音乐联合发起\\\"}\",\n        \"count\": 3,\n        \"labels\": [\"谱乐 AI\", \"海葵音乐\", \"海星音乐\"]\n      },\n      {\n        \"title\": \"三大参与通道\",\n        \"count\": 3,\n        \"buttons\": [\"原创出道季\", \"爆款改编季\", \"精英直签\"]\n      },\n      {\n        \"type\": \"footer\",\n        \"text\": \"{argument name=\\\"call to action\\\" default=\\\"扫码加入 YouMind AI 音乐人计划\\\"}\",\n        \"elements\": [\"左侧二维码\", \"右侧发光的黑胶唱片\"]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13798.jpg"]},{"i":7221,"text":"一张从航天器内部透过圆形舷窗望向深邃太空的电影级写实广角镜头。画面左侧，一个 {argument name=\"celestial body left\" default=\"细节极其丰富的巨大新月形月球\"} 占据了视野，展示了在强烈阳光照射下错综复杂的陨石坑和崎岖地形。右侧，一个较小的 {argument name=\"celestial body right\" default=\"新月形地球\"} 散发着蓝色海洋和白色大气云层的光芒。在最左侧的前景中，可见一只 {argument name=\"foreground element\" default=\"穿着深蓝色宇航服的宇航员手臂\"}，肩部带有醒目的 {argument name=\"patch logo\" default=\"NASA\"} 徽章。宇航员正拿着一个显示着复杂蓝色发光用户界面的数字平板电脑。航天器舷窗的边缘勾勒出整个场景，玻璃上微妙的镜头光晕和反射增添了沉浸式的科幻纪录片美感。高对比度，超写实纹理，8k 分辨率。","imgs":["https://r2.qqsrc.com/images/originals/13799.jpg"]},{"i":7222,"text":"一张 {argument name=\"character description\" default=\"留着齐肩波浪卷发、面带温柔微笑的动漫少女\"} 的特写肖像，身穿 {argument name=\"outfit\" default=\"系着领结的校服\"}。图像是手绘在光面白板上的素描，完全使用 {argument name=\"marker color\" default=\"蓝色\"} 白板笔创作。艺术风格呈现出草图感、多变的线条粗细以及粗犷的马克笔阴影，捕捉到一种随性却又极其精湛的动漫插画效果。白板表面右上角细微的光线反射，增强了“拍摄画作”的真实感。","imgs":["https://r2.qqsrc.com/images/originals/13802.jpg"]},{"i":7223,"text":"{\n  \"type\": \"电商落地页设计稿\",\n  \"brand\": \"{argument name=\\\"brand name\\\" default=\\\"LUMIÈRE\\\"}\",\n  \"aesthetic\": \"{argument name=\\\"aesthetic\\\" default=\\\"奢华、极简、优雅、中性色调\\\"}\",\n  \"layout\": {\n    \"header\": {\n      \"logo\": \"{argument name=\\\"brand name\\\" default=\\\"LUMIÈRE\\\"}\",\n      \"navigation\": [\"新品上市\", \"手袋\", \"珠宝\", \"系列\", \"品牌之家\", \"关于我们\"],\n      \"icons\": [\"搜索\", \"用户\", \"购物车\"]\n    },\n    \"sections\": [\n      {\n        \"name\": \"Hero\",\n        \"text\": {\n          \"headline\": \"{argument name=\\\"hero headline\\\" default=\\\"铸就永恒优雅\\\"}\",\n          \"subheadline\": \"艺术与极致品质的交汇。\",\n          \"button\": \"探索系列\"\n        },\n        \"imagery\": \"放置在石质底座上的奶油色结构感手袋，带有品牌名称的丝巾，柔和的叶影\"\n      },\n      {\n        \"name\": \"Product Grid\",\n        \"title\": \"探索我们的世界\",\n        \"count\": 4,\n        \"items\": [\n          { \"image\": \"大理石上的黑色鳄鱼纹手袋\", \"label\": \"手袋\", \"sublabel\": \"探索\" },\n          { \"image\": \"丝绸上的钻石耳钉\", \"label\": \"珠宝\", \"sublabel\": \"探索\" },\n          { \"image\": \"丝绸上配有皮质表带的经典腕表\", \"label\": \"腕表\", \"sublabel\": \"探索\" },\n          { \"image\": \"金色托盘上的白色蜡烛\", \"label\": \"品牌之家\", \"sublabel\": \"探索\" }\n        ]\n      },\n      {\n        \"name\": \"Featured Product\",\n        \"layout\": \"对角线分割\",\n        \"text\": {\n          \"kicker\": \"精选\",\n          \"title\": \"{argument name=\\\"featured product name\\\" default=\\\"Le Sac Éternel\\\"}\",\n          \"description\": \"持久风格的宣言。\",\n          \"link\": \"立即探索\"\n        },\n        \"imagery\": \"大理石台面上的黑色结构感手袋，配有金色扣环\"\n      },\n      {\n        \"name\": \"Brand Story\",\n        \"layout\": \"双栏布局\",\n        \"imagery\": \"被绿叶环绕的巴黎奥斯曼式建筑\",\n        \"text\": {\n          \"kicker\": \"LUMIÈRE 故事\",\n          \"headline\": \"{argument name=\\\"story headline\\\" default=\\\"传承。工艺。愿景。\\\"}\",\n          \"body\": \"Lumière 诞生于巴黎中心地带，数代以来一直是精致奢华的象征。我们的作品由大师级工匠精心打造，融合了永恒的设计与对细节的极致追求。\",\n          \"link\": \"探索我们的故事\",\n          \"watermark\": \"淡雅的圆形 L 标志\"\n        }\n      },\n      {\n        \"name\": \"Trust Bar\",\n        \"count\": 4,\n        \"items\": [\n          { \"icon\": \"钻石\", \"title\": \"卓越品质\", \"subtitle\": \"精湛工艺\" },\n          { \"icon\": \"卡车\", \"title\": \"免费配送\", \"subtitle\": \"已投保且需签名签收\" },\n          { \"icon\": \"礼盒\", \"title\": \"专属服务\", \"subtitle\": \"个人导购与护理\" },\n          { \"icon\": \"耳机\", \"title\": \"客户服务\", \"subtitle\": \"+33 1 42 86 95 28\" }\n        ]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13803.jpg"]},{"i":7224,"text":"一张写实风格的年轻亚裔女性肖像，侧面视角，留着 {argument name=\"hair style and color\" default=\"黑色短波波头和刘海\"}。她正在 {argument name=\"action\" default=\"抽烟\"}，右手将烟卷递至唇边，一缕淡淡的蓝色烟雾升起。她 {argument name=\"setting\" default=\"在夜晚倚靠着金属阳台栏杆\"}。她穿着 {argument name=\"clothing\" default=\"白色吊带背心和一件从肩头滑落的浅灰色大码开衫\"}，露出了裸露的肩膀和背部。她戴着一枚小珍珠耳环。背景是一片漆黑，伴有模糊的暖色城市灯光。画面呈现出 {argument name=\"aesthetic\" default=\"电影感、情绪化的氛围，带有明显的胶片颗粒感和直闪摄影美学\"}。","imgs":["https://r2.qqsrc.com/images/originals/13806.jpg"]},{"i":7225,"text":"一张暗黑奇幻风格的动漫插画，描绘了一名孤胆剑客站在荒凉的战场上，头顶是一轮巨大的 {argument name=\"moon color\" default=\"血红色\"} 月亮。角色拥有 {argument name=\"character hair\" default=\"凌乱高马尾的长黑发\"} 和发光的红眼，身穿破烂的黑色传统服饰，手持一把向下倾斜的 {argument name=\"weapon\" default=\"武士刀\"}。背景中，一座 {argument name=\"background structure\" default=\"破败的日本城堡\"} 在暗沉、翻涌的云层中若隐若现。场景中包含 3 面插在阴影废墟间的破旧旗帜，上面印有日本汉字。光影效果具有电影质感且充满不祥气息，采用了 {argument name=\"color palette\" default=\"深黑色与浓郁绯红色\"} 的配色方案。","imgs":["https://r2.qqsrc.com/images/originals/13809.jpg"]},{"i":7226,"text":"一张高度精细、错综复杂的 {argument name=\"art style\" default=\"黑白线条艺术插图\"}，主体为 {argument name=\"subject\" default=\"动漫风格天使\"}。她留着飘逸的长波浪卷发，戴着 {argument name=\"headpiece\" default=\"由玫瑰和百合组成的花冠\"}，用一双大而富有表现力的眼睛直视观众。她的 {argument name=\"pose\" default=\"双手合十祈祷\"}。她背部伸展着巨大的羽毛天使翅膀，身穿一件极其华丽的连衣裙，上面覆盖着密集的碎花图案、蕾丝和金银丝，并佩戴着精致的珠宝项圈和吊坠耳环。她脑后是一个光芒四射的圆环，带有笔直的太阳光芒线条。整个背景充满了对称的巴洛克风格花卉和藤蔓金银丝，营造出一种致密的挂毯式框架。整体风格严格采用单色，类似于高度复杂的墨水画、雕刻作品或精致的成人填色书页面，线条刻画极其细致。","imgs":["https://r2.qqsrc.com/images/originals/13810.jpg"]},{"i":7227,"text":"{\n  \"type\": \"建筑施工图\",\n  \"subject\": \"户外景观标识\",\n  \"style\": \"黑白技术线条图，精确尺寸，工程标注，中文注释\",\n  \"sign_details\": {\n    \"main_text\": \"{argument name=\\\"main sign text\\\" default=\\\"hi Park\\\"}\",\n    \"sub_text\": \"{argument name=\\\"sub sign text\\\" default=\\\"天府公园运动中心\\\"}\",\n    \"english_sub_text\": \"West Entrance\"\n  },\n  \"layout\": {\n    \"diagrams_count\": 8,\n    \"sections\": [\n      {\n        \"position\": \"左上\",\n        \"title\": \"① 立面图 1:20\",\n        \"description\": \"展示整体尺寸及指向文字与基座的标注的前立面图。\"\n      },\n      {\n        \"position\": \"中上\",\n        \"title\": \"② 侧立面图 1:20\",\n        \"description\": \"展示深度尺寸的侧立面图。\"\n      },\n      {\n        \"position\": \"右上\",\n        \"elements\": [\n          {\n            \"type\": \"table\",\n            \"title\": \"材质与颜色表\",\n            \"rows\": 6,\n            \"columns\": 4\n          },\n          {\n            \"type\": \"text_block\",\n            \"title\": \"材质说明：\",\n            \"points_count\": 3\n          },\n          {\n            \"type\": \"text_block\",\n            \"title\": \"结构说明：\",\n            \"points_count\": 3\n          }\n        ]\n      },\n      {\n        \"position\": \"左中\",\n        \"title\": \"③ 平面图 1:20\",\n        \"description\": \"带有水平尺寸的俯视平面图。\"\n      },\n      {\n        \"position\": \"右中\",\n        \"title\": \"④ 1-1 剖面图 1:20\",\n        \"description\": \"展示基础和地面高度的横截面图。\"\n      },\n      {\n        \"position\": \"底部\",\n        \"description\": \"四个包含在虚线框内的详细节点图。\",\n        \"details\": [\n          \"⑤ 节点 A 字母与基座连接详图 1:5\",\n          \"⑥ 节点 B 基座与地面固定详图 1:5\",\n          \"⑦ 预埋件详图 1:10\",\n          \"⑧ 基础做法详图 1:15\"\n        ]\n      }\n    ],\n    \"footer\": {\n      \"position\": \"底边\",\n      \"blocks\": [\n        {\n          \"title\": \"施工说明：\",\n          \"points_count\": 4\n        },\n        {\n          \"title\": \"技术要求：\",\n          \"points_count\": 3\n        },\n        {\n          \"title\": \"图签\",\n          \"fields\": [\n            \"图名：{argument name=\\\"project title\\\" default=\\\"景观小品施工图\\\"}\",\n            \"图号：{argument name=\\\"drawing number\\\" default=\\\"LP-01\\\"}\",\n            \"比例：见图\",\n            \"日期：{argument name=\\\"drawing date\\\" default=\\\"2024.05\\\"}\"\n          ]\n        }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13811.jpg"]},{"i":7228,"text":"{\n  \"type\": \"植物与营养信息图海报\",\n  \"subject\": {\n    \"name\": \"{argument name=\\\"subject name\\\" default=\\\"灵芝\\\"}\",\n    \"scientific_name\": \"{argument name=\\\"scientific name\\\" default=\\\"Ganoderma lucidum\\\"}\",\n    \"image\": \"大型、细节丰富的插图，展示了一朵带有同心生长环的红褐色光泽灵芝，位于顶部中央\"\n  },\n  \"layout\": {\n    \"style\": \"简洁、现代、网格化，浅米色背景配以细微的网格线、极简图标及数据可视化元素\",\n    \"sections\": [\n      {\n        \"title\": \"页眉/简介 (左上)\",\n        \"content\": \"大标题文字、学名、标签（'多孔菌科·灵芝属', '药食同源'）、简短描述文字、产地分布图（中国/东亚）以及季节性时间轴柱状图。\"\n      },\n      {\n        \"title\": \"1 营养成分详解 (每 100g) (右上)\",\n        \"content\": \"营养成分分解。包括显示热量（295 kcal）的环形图、宏量营养素（蛋白质、碳水化合物、脂肪等）百分比表格、维生素和矿物质的双柱状图，以及 GI 指数滑块（值为 15）。\"\n      },\n      {\n        \"title\": \"2 健康功效地图 (中左)\",\n        \"content\": \"健康功效地图。特色人体轮廓图，带有 6 个标注点，连接到图标和文字块，描述其功效（如免疫调节、抗衰老、护肝、助眠、调节血糖/血脂、肿瘤辅助治疗），每项均配有 5 星评分。\"\n      },\n      {\n        \"title\": \"3 烹饪方法矩阵 (中中)\",\n        \"content\": \"烹饪方法矩阵。3x3 的 9 个图标网格，代表不同的处理方式（煮、炖、泡茶、煮粥、蒸、炒、泡酒、研粉、烤、凉拌）。每项包含温度/时间、营养保留百分比及星级评分。\"\n      },\n      {\n        \"title\": \"4 四季食用指南 (中右)\",\n        \"content\": \"四季食用指南。围绕中心灵芝图标分为四个象限（春、夏、秋、冬）的圆形图，详细说明季节性益处及最佳食用期（7-10 个月）。\"\n      },\n      {\n        \"title\": \"5 黄金搭配矩阵 (下左)\",\n        \"content\": \"黄金搭配矩阵。3x3 网格，展示围绕中心灵芝的 8 种互补食材（枸杞、红枣、黄芪、银耳、山药、莲子、桂圆、陈皮），并附有解释协同效应的文字。\"\n      },\n      {\n        \"title\": \"6 适宜人群画像 (下中)\",\n        \"content\": \"适宜人群画像。针对 7 类用户群体（儿童、孕妇、老年人、运动员、亚健康人群、免疫力低下者、高血压患者）的图标和文字，展示建议每日摄入量及星级评分。\"\n      },\n      {\n        \"title\": \"7 禁忌与注意事项 (下右)\",\n        \"content\": \"禁忌与注意事项。列表格式，配有警告图标，涵盖不适宜人群、过敏警告、药物相互作用及每日最大摄入量建议。\"\n      },\n      {\n        \"title\": \"8 选购与储存指南 (下左，第 5 部分下方)\",\n        \"content\": \"选购与储存指南。包含新鲜度核对清单、质量等级表（特级、一级、二级、三级）及星级评分、储存条件图标（温度、湿度、保质期）以及保质期时间轴。\"\n      },\n      {\n        \"title\": \"9 趣味知识扩展 (下右，第 7 部分下方)\",\n        \"content\": \"趣味知识扩展。文字块涵盖历史传说、别名、全球产量数据（5 万吨，中国占 85%）及可持续性评分（A 级）。\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13812.jpg"]},{"i":7229,"text":"{\n  \"type\": \"YouTube 缩略图\",\n  \"style\": \"动漫风格，前卫，霓虹粉与黑色配色，带有颓废风和喷溅装饰\",\n  \"character\": {\n    \"appearance\": \"动漫少女，{argument name=\\\"hair color\\\" default=\\\"银色\\\"} 头发，猫耳，紫色双眸\",\n    \"expression\": \"{argument name=\\\"expression\\\" default=\\\"震惊且冒汗\\\"}，张嘴\",\n    \"accessories\": \"带有粉色十字架的黑色猫咪发夹，带有心形环的黑色颈圈\",\n    \"action\": \"手持带有漩涡标志的粉色智能手机\"\n  },\n  \"layout\": {\n    \"main_title\": {\n      \"position\": \"底部居中\",\n      \"style\": \"巨大、粗体、3D 字体，带有颓废质感\",\n      \"lines\": [\n        { \"text\": \"{argument name=\\\"main title top\\\" default=\\\"争议话题\\\"}\", \"color\": \"霓虹粉\" },\n        { \"text\": \"{argument name=\\\"main title bottom\\\" default=\\\"在线阅读 ;;\\\"}\", \"color\": \"白色\" }\n      ]\n    },\n    \"ui_elements\": [\n      {\n        \"type\": \"社交媒体信息流模拟\",\n        \"position\": \"中左\",\n        \"header\": \"← 话题\",\n        \"post_count\": 3,\n        \"details\": \"头像，中文文本，点赞、评论、转发的交互图标\"\n      },\n      {\n        \"type\": \"实时聊天模拟\",\n        \"position\": \"右侧边缘\",\n        \"message_count\": 4,\n        \"details\": \"粉色用户图标，中文文本\"\n      }\n    ],\n    \"text_callouts\": [\n      {\n        \"type\": \"尖刺状对话气泡\",\n        \"position\": \"顶部居中\",\n        \"text\": \"{argument name=\\\"speech bubble text\\\" default=\\\"这真的对吗？;;\\\"}\"\n      },\n      {\n        \"type\": \"霓虹灯箱\",\n        \"position\": \"右上角\",\n        \"text\": \"实时反应中\"\n      },\n      {\n        \"type\": \"漂浮的颓废风文字\",\n        \"position\": \"最左侧\",\n        \"line_count\": 3,\n        \"text\": [\"OO 争议\", \"震惊真相\", \"史诗级事件\"]\n      },\n      {\n        \"type\": \"带有箭头的手写文字\",\n        \"position\": \"右下角\",\n        \"text\": \"你们怎么看？\"\n      }\n    ],\n    \"logos\": [\n      {\n        \"type\": \"应用图标\",\n        \"position\": \"左上角\",\n        \"description\": \"黑色圆角方块上的白色漩涡标志\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13813.jpg"]},{"i":7230,"text":"{\n  \"type\": \"{argument name=\\\"theme\\\" default=\\\"日常作息闪卡\\\"}\",\n  \"style\": \"{argument name=\\\"style\\\" default=\\\"可爱的童书插画风格，柔和的马卡龙色调\\\"}\",\n  \"character\": \"{argument name=\\\"character\\\" default=\\\"扎着两个小辫子、留着棕色短发的幼儿女孩\\\"}\",\n  \"layout\": {\n    \"grid\": \"2x5 格\",\n    \"elements_per_panel\": [\"数字圆圈\", \"标题\", \"场景\", \"带有放大镜图标的问题横幅\"]\n  },\n  \"panels\": [\n    {\"id\": 1, \"title\": \"小宝宝起床啦\", \"scene\": \"起床，太阳，泰迪熊\", \"question\": \"宝宝在哪里？\"},\n    {\"id\": 2, \"title\": \"宝宝在刷牙\", \"scene\": \"刷牙，蓝色睡衣\", \"question\": \"牙刷在哪里？\"},\n    {\"id\": 3, \"title\": \"宝宝吃早餐\", \"scene\": \"吃吐司和鸡蛋，苹果围兜\", \"question\": \"宝宝在吃什么？\"},\n    {\"id\": 4, \"title\": \"宝宝要出门啦\", \"scene\": \"黄色外套，书包，门\", \"question\": \"门在哪里？\"},\n    {\"id\": 5, \"title\": \"宝宝在玩球\", \"scene\": \"在户外踢球，蝴蝶\", \"question\": \"球在哪里？\"},\n    {\"id\": 6, \"title\": \"宝宝在喝水\", \"scene\": \"用学饮杯喝水\", \"question\": \"杯子在哪里？\"},\n    {\"id\": 7, \"title\": \"宝宝吃饭啦\", \"scene\": \"吃米饭，樱桃围兜，餐盘\", \"question\": \"勺子在哪里？\"},\n    {\"id\": 8, \"title\": \"宝宝在洗澡\", \"scene\": \"浴缸，泡泡，小黄鸭\", \"question\": \"泡泡在哪里？\"},\n    {\"id\": 9, \"title\": \"宝宝在看书\", \"scene\": \"在懒人沙发上看书\", \"question\": \"书在哪里？\"},\n    {\"id\": 10, \"title\": \"宝宝睡觉啦\", \"scene\": \"在床上睡觉，夜间的窗户\", \"question\": \"宝宝闭眼了吗？\"}\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/13814.jpg"]},{"i":7231,"text":"一张自信的女性摔跤手站在擂台上的动漫插图。她留着 {argument name=\"hair color\" default=\"金色\"} 的高马尾，系着粉色蝴蝶结。她身穿一件 {argument name=\"outfit color\" default=\"粉色\"} 连体紧身衣，配有白色和金色装饰，搭配同色系的露指手套和及膝系带靴。她在明亮的体育场聚光灯下叉腰摆出姿势，背景是模糊的观众。左下角有一个风格化的 Logo，写着“{argument name=\"logo text\" default=\"Sunset Emilia\"}”。画面风格具有细腻的阴影处理和光泽感的皮肤高光。","imgs":["https://r2.qqsrc.com/images/originals/13815.jpg"]},{"i":7232,"text":"一张超写实、电影质感的镜头，场景设定在 {argument name=\"location\" default=\"白宫新闻发布厅\"}。讲台后坐着 {argument name=\"seated character\" default=\"Sam Altman\"}，他身穿深色西装，系着蓝色领带，神情显得局促不安、紧张万分，正茫然地注视着前方。站在他身后的是 {argument name=\"standing character\" default=\"《黑袍纠察队》中的祖国人 (Homelander)\"}，他穿着标志性的蓝色超级英雄制服，戴着红色手套，肩章上有金色鹰徽。这位站立的角色一只戴着红色手套的手沉重且充满压迫感地搭在坐着的人的肩膀上，另一只手则拿着一瓶 {argument name=\"beverage\" default=\"玻璃瓶装牛奶\"} 喝着，脸上带着自信且略显疯狂的冷笑。背景左侧有一面美国国旗，墙上挂着蓝色的椭圆形白宫徽章。讲台上写着 \"THE WHITE HOUSE WASHINGTON\" 字样。","imgs":["https://r2.qqsrc.com/images/originals/13816.jpg"]},{"i":7233,"text":"{\n  \"type\": \"综合概念艺术与角色参考表\",\n  \"overall_aesthetic\": \"深渊暗黑风格，高细节，{argument name=\\\"theme color\\\" default=\\\"生物发光蓝\\\"} 点缀，生物机械感\",\n  \"header\": {\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"深渊界 Abyss Covenant\\\"}\",\n    \"subtitle\": \"认知即改变，理解即蜕变。\",\n  },\n  \"layout\": {\n    \"top_section\": {\n      \"type\": \"环境与生物概念艺术\",\n      \"description\": \"水下深渊景观，包含 {argument name=\\\"creature type\\\" default=\\\"巨型蛇形利维坦\\\"} 和高耸的有机结构\",\n      \"labeled_entities\": {\n        \"count\": 4,\n        \"labels\": [\"01 长者塞菲拉 (Elder Sephira)\", \"02 沃兰 (Volan)\", \"03 涅瑞伊得 (Nereis)\", \"04 深渊核 (Abyssal Core)\"]\n      },\n      \"sub_panels\": [\n        {\n          \"title\": \"契约者装备\",\n          \"count\": 4,\n          \"description\": \"生物机械武器与工具\"\n        },\n        {\n          \"title\": \"比例整合图\",\n          \"count\": 4,\n          \"description\": \"人类、生物与结构的轮廓尺寸对比\"\n        }\n      ]\n    },\n    \"bottom_section\": {\n      \"type\": \"角色设计表\",\n      \"character\": {\n        \"name\": \"{argument name=\\\"character name\\\" default=\\\"长者塞菲拉 - ELDER SEPHIRA -\\\"}\",\n        \"design\": \"女性，深色乱发丸子头，身着 {argument name=\\\"suit style\\\" default=\\\"带有半透明披风的复杂深色生物机械装甲\\\"}\"\n      },\n      \"turnaround_poses\": {\n        \"count\": 4,\n        \"labels\": [\"正面图 FRONT\", \"侧面图 LEFT SIDE\", \"背面图 BACK\", \"参考：三视图 (3/4)\"]\n      },\n      \"expressions\": {\n        \"title\": \"表情集 EXPRESSIONS\",\n        \"count\": 3,\n        \"labels\": [\"通常（深层专注）\", \"契约激活时\", \"私下瞬间\"]\n      },\n      \"detail_panels\": [\n        {\n          \"title\": \"瞳孔变化\",\n          \"count\": 2,\n          \"description\": \"展示瞳孔变化的眼部特写\"\n        },\n        {\n          \"title\": \"装甲细节\",\n          \"count\": 2,\n          \"description\": \"胸部与背部装甲核心结构图\"\n        },\n        {\n          \"title\": \"手部细节 / 靴子与足底\",\n          \"count\": 2,\n          \"description\": \"手套与靴子特写\"\n        }\n      ],\n      \"bottom_row\": [\n        {\n          \"title\": \"便携工具 / 数据设备\",\n          \"count\": 5,\n          \"description\": \"手持设备与胶囊\"\n        },\n        {\n          \"title\": \"尺寸对比标尺\",\n          \"count\": 4,\n          \"description\": \"辅助尺寸对比图表\"\n        },\n        {\n          \"title\": \"契约纹章\",\n          \"count\": 1,\n          \"description\": \"发光的圆形纹章\"\n        }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13817.jpg"]},{"i":7234,"text":"{\n  \"type\": \"网络研讨会宣传横幅\",\n  \"style\": \"现代风格，醒目排版，高对比度，对角线分割布局\",\n  \"background\": {\n    \"pattern\": \"覆盖整个画布的 40 个从 01 到 40 的序列数字组成的淡网格\",\n    \"left_color\": \"鲜艳的洋红色\",\n    \"right_color\": \"黑色\",\n    \"split_style\": \"从顶部中心到左下角的锐利对角线\"\n  },\n  \"left_section\": {\n    \"top_label\": \"{argument name=\\\"top label\\\" default=\\\"note 会员专属网络研讨会\\\"}\",\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"Claude Code\\\"}\",\n    \"highlight_box_1\": {\n      \"text\": \"{argument name=\\\"highlight text 1\\\" default=\\\"不知道就会\\\"}\",\n      \"style\": \"白色倾斜矩形背景上的黑色文字\"\n    },\n    \"highlight_box_2\": {\n      \"text\": \"{argument name=\\\"highlight text 2\\\" default=\\\"吃亏\\\"}\",\n      \"style\": \"白色倾斜矩形背景上的黑色文字\"\n    },\n    \"bottom_text\": \"40 个技巧\"\n  },\n  \"right_section\": {\n    \"top_right_label\": \"KAWAI LAB Vol.5\",\n    \"subject\": \"一位年轻日本女性的肖像，齐肩深色短发配刘海，身穿黑色圆领毛衣，表情自然，注视镜头\",\n    \"middle_badge\": {\n      \"text\": \"限前 100 名\",\n      \"style\": \"带有垂直线条装饰的白色文字\"\n    },\n    \"bottom_right_date\": \"{argument name=\\\"date and time\\\" default=\\\"4 月 24 日 周五 12:10 - 12:50\\\"}\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13818.jpg"]},{"i":7235,"text":"{\n  \"type\": \"18 面板品牌识别与角色设计文档\",\n  \"brand\": {\n    \"name\": \"{argument name=\\\"brand name\\\" default=\\\"沐阳 MUYANG TEA\\\"}\",\n    \"industry\": \"{argument name=\\\"industry\\\" default=\\\"茶饮店\\\"}\",\n    \"colors\": [\"{argument name=\\\"primary color\\\" default=\\\"黄色\\\"}\", \"{argument name=\\\"secondary color\\\" default=\\\"绿色\\\"}\", \"白色\", \"棕色\", \"深绿色\"]\n  },\n  \"subject\": \"{argument name=\\\"character description\\\" default=\\\"佩戴绿色围裙的 3D 渲染可爱柴犬吉祥物\\\"}\",\n  \"layout\": {\n    \"grid\": \"3 列 6 行\",\n    \"sections\": [\n      {\n        \"title\": \"01 品牌 DNA 分析 / BRAND DNA ANALYSIS\",\n        \"elements\": [\"Logo\", \"5 个色卡\", \"6 个图标\", \"目标受众图表\"]\n      },\n      {\n        \"title\": \"02 概念构思 / CONCEPT MOODBOARD\",\n        \"elements\": [\"5 张参考照片\", \"4 个情绪图标\", \"设计公式\"]\n      },\n      {\n        \"title\": \"03 形态研究 / FORM STUDY\",\n        \"elements\": [\"4 个 Logo 解构图标\", \"4 个演变步骤\", \"4 个轮廓图\"]\n      },\n      {\n        \"title\": \"04 概念探索 / CONCEPT EXPLORATION\",\n        \"elements\": [\"12 个角色线稿草图\"]\n      },\n      {\n        \"title\": \"05 精细线稿 / REFINED LINE ART\",\n        \"elements\": [\"3 行带有比例参考的正侧面线稿\"]\n      },\n      {\n        \"title\": \"06 细节精修 / DETAIL REFINEMENT\",\n        \"elements\": [\"2 个带标注的全身渲染图\", \"4 个圆形特写图\"]\n      },\n      {\n        \"title\": \"07 表情设定 / EXPRESSION SHEET\",\n        \"elements\": [\"11 个 3D 渲染头部表情\"]\n      },\n      {\n        \"title\": \"08 姿势库 / POSE LIBRARY\",\n        \"elements\": [\"9 个全身 3D 渲染姿势\"]\n      },\n      {\n        \"title\": \"09 转身视图 / TURNAROUND VIEW\",\n        \"elements\": [\"5 个全身 3D 渲染图\", \"5 个对应的线稿视图\"]\n      },\n      {\n        \"title\": \"10 色彩开发 / COLOR DEVELOPMENT\",\n        \"elements\": [\"5 行 5 色配色方案\", \"色彩心理学文字\"]\n      },\n      {\n        \"title\": \"11 材质规格 / MATERIAL SPECIFICATION\",\n        \"elements\": [\"5 个纹理色卡\", \"属性滑块\", \"4 个制造工艺图标\"]\n      },\n      {\n        \"title\": \"12 色彩应用 / COLOR APPLICATION\",\n        \"elements\": [\"4 个配色变体渲染图\", \"2 个明暗渲染图\", \"4 个对比度评分圆圈\"]\n      },\n      {\n        \"title\": \"13 构造指南 / CONSTRUCTION GUIDE\",\n        \"elements\": [\"2 个几何结构与网格线稿图\"]\n      },\n      {\n        \"title\": \"14 设计系统规则 / DESIGN SYSTEM RULES\",\n        \"elements\": [\"最小尺寸图标\", \"安全空间示意图\", \"4 个使用示例\"]\n      },\n      {\n        \"title\": \"15 资产变体 / ASSET VARIANTS\",\n        \"elements\": [\"3 个尺寸变体\", \"3 个线稿变体\", \"3 个简化扁平化头像\"]\n      },\n      {\n        \"title\": \"16 数字应用 / DIGITAL APPLICATIONS\",\n        \"elements\": [\"1 个 App 图标\", \"2 个社交媒体头像\", \"UI 元素\", \"3 帧动画循环\"]\n      },\n      {\n        \"title\": \"17 实物应用 / PHYSICAL APPLICATIONS\",\n        \"elements\": [\"毛绒玩具样机\", \"包装样机\", \"周边商品样机\", \"店面样机\"]\n      },\n      {\n        \"title\": \"18 最终主视觉 / FINAL RENDERING\",\n        \"elements\": [\"吉祥物手持茶饮的大尺寸高分辨率 3D 渲染图\", \"Logo\", \"文件格式列表\"]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13819.jpg"]},{"i":7236,"text":"{\n  \"type\": \"桌面视频平台 UI 模型\",\n  \"theme\": \"深色模式\",\n  \"header\": {\n    \"logo\": \"YouTube IN\",\n    \"search_bar\": \"居中，带有放大镜图标\",\n    \"right_icons\": {\n      \"count\": 4,\n      \"items\": [\"麦克风\", \"+ 创建按钮\", \"通知铃铛\", \"用户头像\"]\n    }\n  },\n  \"video_player\": {\n    \"scene\": \"演播室场景，两位科技博主坐在桌前。\",\n    \"subjects\": [\n      \"{argument name=\\\"left person\\\" default=\\\"Marques Brownlee (MKBHD)\\\"} 身穿黑色 T 恤\",\n      \"{argument name=\\\"right person\\\" default=\\\"Arun Maini (Mrwhosetheboss)\\\"} 身穿绿色衬衫\",\n      \"{argument name=\\\"robot model\\\" default=\\\"Tesla Optimus 人形机器人\\\"} 站在他们中间\"\n    ],\n    \"props\": [\"带有 Logo 的黑色马克杯\", \"带有发光蓝色霓虹 M Logo 的背景屏幕\"],\n    \"controls_bar\": {\n      \"progress_bar\": \"红色，接近起始位置\",\n      \"timestamp\": \"0:01 / 18:47\",\n      \"left_icons\": {\n        \"count\": 3,\n        \"items\": [\"播放/暂停\", \"下一首\", \"音量\"]\n      },\n      \"right_icons\": {\n        \"count\": 6,\n        \"items\": [\"CC 字幕\", \"带有 4K 标志的设置\", \"迷你播放器\", \"影院模式\", \"投屏\", \"全屏\"]\n      }\n    }\n  },\n  \"video_details\": {\n    \"title\": \"{argument name=\\\"video title\\\" default=\\\"Tesla Optimus 机器人评测：未来已来！\\\"}\",\n    \"channel_info\": {\n      \"name\": \"{argument name=\\\"channel name\\\" default=\\\"Mrwhosetheboss\\\"}\",\n      \"badges\": [\"认证勾选标记\"],\n      \"subscribers\": \"2050 万订阅者\",\n      \"button\": \"白色订阅按钮\"\n    },\n    \"action_buttons\": {\n      \"count\": 6,\n      \"items\": [\"点赞 (21.5 万) / 点踩 (4200) 胶囊按钮\", \"分享\", \"下载\", \"剪辑\", \"保存\", \"更多 (...)\"]\n    }\n  },\n  \"description_box\": {\n    \"metadata\": \"3,278,456 次观看 2024 年 4 月 12 日 热门趋势第 7 名\",\n    \"text\": \"MKBHD 和我一起评测 Tesla 的 Optimus 人形机器人。我们涵盖了设计、行走、AI、实测以及它对未来的意义！\",\n    \"links\": [\"Marques 的频道: @mkbhd\"]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13820.jpg"]},{"i":7237,"text":"{\n  \"type\": \"教育信息图\",\n  \"header\": {\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"最新 AI (ChatGPT / Claude) 的运行机制\\\"}\",\n    \"badge\": \"{argument name=\\\"target audience badge\\\" default=\\\"高中生也能看懂！\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"一张图带你了解 AI 如何理解文字、图像、音频并进行思考与行动！\\\"}\"\n  },\n  \"layout\": {\n    \"style\": \"简洁、扁平化设计、结构化网格、中文文本\",\n    \"sections\": [\n      {\n        \"title\": \"AI 输出答案的过程 (基本流程)\",\n        \"position\": \"左侧栏\",\n        \"count\": 6,\n        \"labels\": [\"输入\", \"分词 (Tokenization)\", \"向量化 (Embedding)\", \"Transformer (AI 的大脑)\", \"预测下一个 Token (生成)\", \"输出\"],\n        \"visuals\": \"带有箭头的垂直流程、使用笔记本电脑的男孩、分词示意图、向量数字数组、自注意力机制树、机器人图标\"\n      },\n      {\n        \"title\": \"核心要点：3 大关键点\",\n        \"position\": \"右上角\",\n        \"count\": 3,\n        \"labels\": [\"Token (词元)\", \"Transformer (转换器)\", \"下一词元预测\"],\n        \"visuals\": \"分词模块、自注意力节点网络、词语预测序列\"\n      },\n      {\n        \"title\": \"近期突破 (2024-2025 年)\",\n        \"position\": \"右侧中部\",\n        \"count\": 4,\n        \"labels\": [\"多模态\", \"Agent 化\", \"长文本与推理能力提升\", \"效率与速度优化\"],\n        \"visuals\": \"图像/音频/文本图标、机器人 Agent 流程图、灯泡与书籍、带有 3 个专家节点的速度计\"\n      },\n      {\n        \"title\": \"总结\",\n        \"position\": \"底部全宽\",\n        \"elements\": [\n          \"水平 6 步流程图\",\n          \"黄色总结框，文本内容：{argument name=\\\"summary text\\\" default=\\\"AI 是一个巨大的数学机器，它将信息拆解并转换为数字，通过计算关系来预测下一个出现的内容！\\\"}\",\n          \"{argument name=\\\"character style\\\" default=\\\"动漫风格女学生，正在指引并微笑\\\"}\"\n        ]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13821.jpg"]},{"i":7238,"text":"{\n  \"type\": \"移动端直播界面模型\",\n  \"subject\": {\n    \"identity\": \"{argument name=\\\"subject name\\\" default=\\\"埃隆·马斯克\\\"}\",\n    \"appearance\": \"身穿黑色 T 恤，印有 {argument name=\\\"t-shirt graphic\\\" default=\\\"星舰火箭和 SPACEX 文字\\\"}\",\n    \"pose\": \"{argument name=\\\"expression\\\" default=\\\"温暖微笑，直视镜头\\\"}，双手交叠放在深色桌面上\"\n  },\n  \"environment\": \"{argument name=\\\"background\\\" default=\\\"SpaceX 办公室，背景有火箭模型和霓虹灯牌\\\"}\",\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"顶部栏 UI\",\n        \"position\": \"顶部\",\n        \"count\": 4,\n        \"labels\": [\n          \"个人资料信息，包含“埃隆·马斯克”和“关注”按钮\",\n          \"观众头像及人数“60.6万”\",\n          \"排名徽章“全站第1名”\",\n          \"关闭按钮“X”\"\n        ]\n      },\n      {\n        \"title\": \"礼物弹窗\",\n        \"position\": \"中左\",\n        \"count\": 2,\n        \"labels\": [\n          \"星辰大海 送小心心 x66 (爱心图标)\",\n          \"Dreamer 送超级火箭 x1 (火箭图标)\"\n        ]\n      },\n      {\n        \"title\": \"聊天流\",\n        \"position\": \"底左\",\n        \"count\": 7,\n        \"labels\": [\n          \"用户12345: 马斯克来了！🔥\",\n          \"钢铁侠本侠: 特斯拉未来规划能分享一下吗？\",\n          \"加密货币王: 会考虑接受狗狗币支付吗？🐶\",\n          \"火星移民: 什么时候去火星？🚀\",\n          \"银河系 来了\",\n          \"智者无敌: 第一排支持马斯克！\",\n          \"未来已来: 👍👍👍\"\n        ]\n      },\n      {\n        \"title\": \"侧边操作按钮\",\n        \"position\": \"底右\",\n        \"count\": 4,\n        \"labels\": [\n          \"主播头像及“+”号\",\n          \"点赞爱心“38.7万”\",\n          \"评论气泡“6.2万”\",\n          \"分享箭头“3.6万”\"\n        ]\n      },\n      {\n        \"title\": \"底部输入栏\",\n        \"position\": \"底部\",\n        \"count\": 3,\n        \"labels\": [\n          \"文本输入框“说点什么...”\",\n          \"礼物盒图标\",\n          \"更多选项“...”\"\n        ]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13822.jpg"]},{"i":7239,"text":"{\n  \"type\": \"日式宣传横幅广告\",\n  \"background\": \"鲜艳的红色，带有精致的樱花图案和金色纸屑\",\n  \"character\": {\n    \"style\": \"动漫风\",\n    \"appearance\": \"留着黑色长辫的年轻女性，侧头戴着狐狸面具\",\n    \"outfit\": \"{argument name=\\\"character outfit\\\" default=\\\"红白相间的巫女服，配有装饰性结扣\\\"}\",\n    \"pose\": \"眨眼、充满活力地微笑，指向产品杯\"\n  },\n  \"product\": {\n    \"description\": \"杯装方便面模型\",\n    \"design\": \"红白相间的包装，印有 'COP NEEDLE' 和 '醤油味' 字样\"\n  },\n  \"food_shot\": {\n    \"description\": \"一大碗热气腾腾的拉面\",\n    \"toppings\": [\"3 只虾\", \"肉块\", \"半个溏心蛋\", \"葱花\", \"蛋碎\"]\n  },\n  \"typography_and_layout\": {\n    \"text_elements_count\": 8,\n    \"elements\": [\n      { \"position\": \"左上角星形光芒\", \"text\": \"{argument name=\\\"top left burst text\\\" default=\\\"新発売!\\\"}\" },\n      { \"position\": \"顶部中央巨大 3D 标题\", \"text\": \"{argument name=\\\"main product name\\\" default=\\\"コップヌードル\\\"}\" },\n      { \"position\": \"主标题下方胶囊框\", \"text\": \"醤油味\" },\n      { \"position\": \"中央黄色锯齿状光芒\", \"text\": \"お湯を注いで 3分!\" },\n      { \"position\": \"中右侧浮动文字\", \"text\": \"{argument name=\\\"catchphrase text\\\" default=\\\"だし香る、やさしい味わい！コクうまスープ！\\\"}\" },\n      { \"position\": \"左下角对话气泡\", \"text\": \"巫女ちゃんおすすめ!\" },\n      { \"position\": \"底部中央文字\", \"text\": \"小腹がすいたらこれ!\" },\n      { \"position\": \"右下角红色价格框\", \"text\": \"{argument name=\\\"price text\\\" default=\\\"198円\\\"}\" }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13823.jpg"]}];